using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using POS.Server.Data;using POS.Shared.DTOs;
namespace POS.Server.Controllers;
[ApiController,Route("api/reports"),Authorize]public class ReportsController(AppDbContext db):ControllerBase
{
 [HttpGet("production"),Authorize(Roles="Administrador,Producción,Gerencia")]public async Task<List<ProductionReportRow>>Production(DateTime? from,DateTime? to){var q=db.ProductionLots.AsNoTracking().Include(x=>x.Product).AsQueryable();if(from.HasValue)q=q.Where(x=>x.StartDate>=from);if(to.HasValue)q=q.Where(x=>x.StartDate<to.Value.Date.AddDays(1));return await q.OrderByDescending(x=>x.StartDate).Select(x=>new ProductionReportRow{Code=x.Code,ProductName=x.Product!.Name,StartDate=x.StartDate,EndDate=x.EndDate,PlannedQuantity=x.PlannedQuantity,ProducedQuantity=x.ProducedQuantity,Status=x.Status}).ToListAsync();}
 [HttpGet("inventory"),Authorize(Roles="Administrador,Almacén,Gerencia")]public async Task<List<InventoryReportRow>>Inventory(){var p=await db.InventoryProducts.AsNoTracking().Select(x=>new InventoryReportRow{Id=x.Id,ItemType="Producto",Name=x.Name,UnitOfMeasure=x.UnitOfMeasure,CurrentStock=x.CurrentStock,MinimumStock=x.MinimumStock,IsActive=x.IsActive}).ToListAsync();var m=await db.RawMaterials.AsNoTracking().Select(x=>new InventoryReportRow{Id=x.Id,ItemType="Materia prima",Name=x.Name,UnitOfMeasure=x.UnitOfMeasure,CurrentStock=x.CurrentStock,MinimumStock=x.MinimumStock,IsActive=x.IsActive}).ToListAsync();return p.Concat(m).OrderBy(x=>x.ItemType).ThenBy(x=>x.Name).ToList();}
 [HttpGet("dispatches"),Authorize(Roles="Administrador,Almacén,Gerencia")]public async Task<List<DispatchReportRow>>Dispatches(DateTime? from,DateTime? to){var q=db.DispatchDetails.AsNoTracking().Include(x=>x.Dispatch).ThenInclude(x=>x!.User).Include(x=>x.Product).AsQueryable();if(from.HasValue)q=q.Where(x=>x.Dispatch!.Date>=from);if(to.HasValue)q=q.Where(x=>x.Dispatch!.Date<to.Value.Date.AddDays(1));return await q.OrderByDescending(x=>x.Dispatch!.Date).Select(x=>new DispatchReportRow{DispatchId=x.DispatchId,Date=x.Dispatch!.Date,Destination=x.Dispatch.Destination,Username=x.Dispatch.User!.Username,ProductName=x.Product!.Name,Quantity=x.Quantity,Status=x.Dispatch.Status}).ToListAsync();}
}
